package org.apache.commons.lang3.text.translate;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class LookupTranslator_translate_TriageGen2Test {

    @Test
    public void testTranslate_MatchLongestFirst() throws IOException {
        // Setup: "ab" -> "1", "abc" -> "2"
        // Greedy algorithm should pick "abc" if available
        LookupTranslator translator = new LookupTranslator(
                new CharSequence[]{"ab", "1"},
                new CharSequence[]{"abc", "2"}
        );

        StringWriter writer = new StringWriter();
        String input = "abc";

        // Test index 0: should match "abc" (length 3)
        int lengthRead = translator.translate(input, 0, writer);

        assertEquals(3, lengthRead);
        assertEquals("2", writer.toString());
    }

    @Test
    public void testTranslate_MatchShortestAvailable() throws IOException {
        // Setup: "a" -> "1", "ab" -> "2"
        LookupTranslator translator = new LookupTranslator(
                new CharSequence[]{"a", "1"},
                new CharSequence[]{"ab", "2"}
        );

        StringWriter writer = new StringWriter();
        String input = "ab";

        // Test index 0: should match "ab" (length 2)
        int lengthRead = translator.translate(input, 0, writer);

        assertEquals(2, lengthRead);
        assertEquals("2", writer.toString());
    }

    @Test
    public void testTranslate_NoMatch() throws IOException {
        LookupTranslator translator = new LookupTranslator(
                new CharSequence[]{"x", "1"}
        );

        StringWriter writer = new StringWriter();
        String input = "abc";

        // Test index 0: 'a' is not in map
        int lengthRead = translator.translate(input, 0, writer);

        assertEquals(0, lengthRead);
        assertEquals("", writer.toString());
    }

    @Test
    public void testTranslate_IndexOutOfBounds_ClampsToLength() throws IOException {
        // Setup: "abc" -> "1"
        LookupTranslator translator = new LookupTranslator(
                new CharSequence[]{"abc", "1"}
        );

        StringWriter writer = new StringWriter();
        String input = "abc";

        // Test index 2: input.length() - index = 1. 
        // Max becomes 1. Loop checks subSeq(2, 3) -> "c". No match.
        int lengthRead = translator.translate(input, 2, writer);

        assertEquals(0, lengthRead);
        assertEquals("", writer.toString());
    }

    @Test
    public void testTranslate_PartialMatchAtEnd() throws IOException {
        // Setup: "bc" -> "2"
        LookupTranslator translator = new LookupTranslator(
                new CharSequence[]{"bc", "2"}
        );

        StringWriter writer = new StringWriter();
        String input = "abc";

        // Test index 1: input.length() - index = 2.
        // Max is 2. Loop checks "bc". Match!
        int lengthRead = translator.translate(input, 1, writer);

        assertEquals(2, lengthRead);
        assertEquals("2", writer.toString());
    }

    @Test
    public void testTranslate_ExactBoundary() throws IOException {
        // Setup: "a" -> "1"
        LookupTranslator translator = new LookupTranslator(
                new CharSequence[]{"a", "1"}
        );

        StringWriter writer = new StringWriter();
        String input = "a";

        // index + longest (0 + 1) is NOT > input.length (1). 
        // max stays 1.
        int lengthRead = translator.translate(input, 0, writer);

        assertEquals(1, lengthRead);
        assertEquals("1", writer.toString());
    }

    @Test(expected = IOException.class)
    public void testTranslate_ThrowsIOException() throws IOException {
        LookupTranslator translator = new LookupTranslator(
                new CharSequence[]{"a", "1"}
        );

        // Custom writer that throws exception
        class ErrorWriter extends StringWriter {
            @Override
            public void write(String str) throws IOException {
                throw new IOException("Simulated IO Error");
            }
        }

        translator.translate("a", 0, new ErrorWriter());
    }
}
